CREATE TABLE "community_groups" ("id" TEXT NOT NULL,"name" VARCHAR(80) NOT NULL,"description" VARCHAR(500) NOT NULL DEFAULT '',"visibility" TEXT NOT NULL DEFAULT 'PUBLIC',"ownerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "community_groups_pkey" PRIMARY KEY ("id"),CONSTRAINT "community_groups_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "community_groups_visibility_check" CHECK ("visibility" IN ('PUBLIC','PRIVATE')));
CREATE TABLE "community_members" ("id" TEXT NOT NULL,"groupId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "community_members_pkey" PRIMARY KEY ("id"),CONSTRAINT "community_members_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "community_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "community_members_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "community_members_groupId_userId_key" ON "community_members"("groupId","userId");
CREATE INDEX "community_members_userId_idx" ON "community_members"("userId");
CREATE TABLE "community_posts" ("id" TEXT NOT NULL,"groupId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"body" VARCHAR(2000) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "community_posts_pkey" PRIMARY KEY ("id"),CONSTRAINT "community_posts_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "community_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "community_posts_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "community_posts_groupId_createdAt_idx" ON "community_posts"("groupId","createdAt");
